#!/usr/bin/env bash
# init-design-workspace.sh — bootstrap .superdesign/ folder in a project
set -euo pipefail

PROJECT_DIR=${1:-.}
mkdir -p "$PROJECT_DIR/.superdesign"/{design_iterations,design_system,replica_html_template,assets}

if [[ ! -f "$PROJECT_DIR/.superdesign/design-system.md" ]]; then
  cat > "$PROJECT_DIR/.superdesign/design-system.md" <<'EOF'
# Design System

Generated by OpenClaw design-orchestrator skill.

## Principles

- Avoid generic AI-slop UI: no default shadcn everything, no identical card grids.
- One strong visual idea per page/flow.
- Restrained color palette (1-2 accents max).
- Generous whitespace and intentional hierarchy.
- System fonts or one carefully chosen typeface.
- Accessible contrast and focus states.

## Tokens

Update as the project evolves.

### Colors
- `--color-bg`: #ffffff
- `--color-surface`: #f8f8f8
- `--color-text`: #111111
- `--color-muted`: #666666
- `--color-accent`: #0055ff
- `--color-accent-soft`: #e6efff

### Typography
- `--font-body`: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif
- `--font-heading`: inherit
- `--text-xs`: 0.75rem
- `--text-sm`: 0.875rem
- `--text-base`: 1rem
- `--text-lg`: 1.125rem
- `--text-xl`: 1.5rem
- `--text-2xl`: 2rem

### Spacing
- `--space-1`: 0.25rem
- `--space-2`: 0.5rem
- `--space-3": 0.75rem
- `--space-4`: 1rem
- `--space-6`: 1.5rem
- `--space-8`: 2rem
- `--space-12`: 3rem
- `--space-16`: 4rem

### Radius
- `--radius-sm`: 0.25rem
- `--radius-md`: 0.5rem
- `--radius-lg`: 0.75rem

### Shadows
- `--shadow-sm`: 0 1px 2px rgba(0,0,0,0.05)
- `--shadow-md`: 0 4px 12px rgba(0,0,0,0.08)
- `--shadow-lg`: 0 12px 24px rgba(0,0,0,0.12)
EOF
fi

echo "Design workspace ready at $PROJECT_DIR/.superdesign/"
